    "question": "Jika sebuah karakter sprite pada Scratch diberi balok kode: \"Repeat 4 [ Move 50 steps, Turn right 90 degrees ]\", bangun apakah yang akan terbentuk?",
    "options": [
      "Segitiga sama sisi",
      "Lingkaran utuh",
      "Garis lurus panjang",
      "Bujur sangkar (Persegi)"
    ],
